from agent_config_premium.context import CustomerSupportContext from agent_config_premium.access_token import get_gateway_access_token from agent_config_premium.agent_task import agent_task from agent_config_premium.streaming_queue import StreamingQueue from agent_config_premium.jwt_utils import extract_tenant_id_from_jwt from bedrock_agentcore.runtime import BedrockAgentCoreApp from scripts.utils import get_ssm_parameter import asyncio import logging import os
# Environment flags os.environ["STRANDS_OTEL_ENABLE_CONSOLE_EXPORT"] = "true" os.environ["STRANDS_TOOL_CONSOLE_MODE"] = "enabled"
# Use premium knowledge base os.environ["KNOWLEDGE_BASE_ID"] = get_ssm_parameter( "/app/customersupport/premium_knowledge_base/knowledge_base_id" )
# Logging setup logging.basicConfig(level=logging.INFO) logger = logging.getLogger(__name__)
# Bedrock app and global agent instance app = BedrockAgentCoreApp()
@app.entrypoint async def invoke(payload, context): if not CustomerSupportContext.get_response_queue_ctx(): CustomerSupportContext.set_response_queue_ctx(StreamingQueue())
if not CustomerSupportContext.get_gateway_token_ctx(): gateway_token = await get_gateway_access_token() CustomerSupportContext.set_gateway_token_ctx(gateway_token)
# Hardcode tenant_id to premium for premium agent tenant_id = "premium" print(f"🔍 DEBUG: Premium agent hardcoded tenant_id: {tenant_id}") CustomerSupportContext.set_tenant_id_ctx(tenant_id)
user_message = payload["prompt"] actor_id = payload["actor_id"]
session_id = context.session_id
if not session_id: raise Exception("Context session_id is not set")
task = asyncio.create_task( agent_task( user_message=user_message, session_id=session_id, actor_id=actor_id, ) )
response_queue = CustomerSupportContext.get_response_queue_ctx()
async def stream_output(): async for item in response_queue.stream(): yield item await task # Ensure task completion
return stream_output()
if __name__ == "__main__": app.run()

from bedrock_agentcore.memory import MemoryClient
from strands.hooks.events import AgentInitializedEvent, MessageAddedEvent
from strands.hooks.registry import HookProvider, HookRegistry
import copy


class MemoryHook(HookProvider):
    def __init__(
        self,
        memory_client: MemoryClient,
        memory_id: str,
        actor_id: str,
        session_id: str,
    ):
        self.memory_client = memory_client
        self.memory_id = memory_id
        self.actor_id = actor_id
        self.session_id = session_id

    def on_agent_initialized(self, event: AgentInitializedEvent):
        """Load recent conversation history when agent starts"""
        try:
            # Load the last 5 conversation turns from memory
            recent_turns = self.memory_client.get_last_k_turns(
                memory_id=self.memory_id,
                actor_id=self.actor_id,
                session_id=self.session_id,
                k=5,
            )

            if recent_turns:
                # Format conversation history for context
                context_messages = []
                for turn in recent_turns:
                    for message in turn:
                        role = "assistant" if message["role"] == "ASSISTANT" else "user"
                        content = message["content"]["text"]
                        context_messages.append(
                            {"role": role, "content": [{"text": content}]}
                        )

                # context = "\n".join(context_messages)
                # Add context to agent's system prompt.
                event.agent.system_prompt += """
                Do not respond with user preferences or user facts. 
                Strictly use user preferences and user facts to know more about the user.
                Also be aware that this information can be outdated.
                """
                event.agent.messages = context_messages

        except Exception as e:
            print(f"Memory load error: {e}")

    def _add_context_user_query(
        self, namespace: str, query: str, init_content: str, event: MessageAddedEvent
    ):
        content = None
        memories = self.memory_client.retrieve_memories(
            memory_id=self.memory_id, namespace=namespace, query=query, top_k=3
        )

        for memory in memories:
            if not content:
                content = "\n\n" + init_content + "\n\n"

            content += memory["content"]["text"]

            if content:
                event.agent.messages[-1]["content"][0]["text"] += content + "\n\n"

    def on_message_added(self, event: MessageAddedEvent):
        """Store messages in memory"""
        messages = copy.deepcopy(event.agent.messages)
        try:
            if messages[-1]["role"] == "user" or messages[-1]["role"] == "assistant":
                if "text" not in messages[-1]["content"][0]:
                    return

                if messages[-1]["role"] == "user":
                    self._add_context_user_query(
                        namespace=f"support/user/{self.actor_id}/preferences",
                        query=messages[-1]["content"][0]["text"],
                        init_content="These are user preferences:",
                        event=event,
                    )

                    self._add_context_user_query(
                        namespace=f"support/user/{self.actor_id}/facts",
                        query=messages[-1]["content"][0]["text"],
                        init_content="These are user facts:",
                        event=event,
                    )
                self.memory_client.save_conversation(
                    memory_id=self.memory_id,
                    actor_id=self.actor_id,
                    session_id=self.session_id,
                    messages=[
                        (messages[-1]["content"][0]["text"], messages[-1]["role"])
                    ],
                )

        except Exception as e:
            raise RuntimeError(f"Memory save error: {e}")

    def register_hooks(self, registry: HookRegistry):
        registry.add_callback(MessageAddedEvent, self.on_message_added)
        registry.add_callback(AgentInitializedEvent, self.on_agent_initialized)

#!/usr/bin/python
import json import click from bedrock_agentcore.memory import MemoryClient from strands import Agent from strands_tools import calculator import sys import os import uuid import time from strands.models import BedrockModel import boto3
sys.path.insert(0, os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))) from agent_config.memory_hook_provider import MemoryHook from scripts.utils import get_ssm_parameter
# Session & actor configuration ACTOR_ID = "default" SESSION_ID = str(uuid.uuid4()) MEMORY_ID = get_ssm_parameter("/app/customersupport/agentcore/memory_id")
model = BedrockModel( model_id="us.anthropic.claude-3-5-haiku-20241022-v1:0", )
memory_client = boto3.client("bedrock-agentcore")
def setup_agent(): """Setup agent with memory and tools""" memory_client = MemoryClient() memory_hooks = MemoryHook( memory_client=memory_client, memory_id=MEMORY_ID, actor_id=ACTOR_ID, session_id=SESSION_ID, )
agent = Agent( hooks=[memory_hooks], tools=[calculator], system_prompt="You are a helpful personal assistant.", model=model, callback_handler=None, )
return agent, memory_client
@click.group() def cli(): """Memory Testing CLI for Customer Support Assistant""" pass
@cli.command() def load_conversation(): """Load and execute predefined mock conversations to test long-term memory""" conversations = [ "Hi, how are you doing?", "My name is John Smith and I'm having trouble with my account login. Can you help me?", "I'm trying to reset my password but I'm not receiving the verification email.", "My email address is john.smith@email.com and my account was created about 6 months ago.", "Actually, let me also mention that I have a premium subscription plan.", "Can you calculate what 15% of 240 would be? I need to figure out my discount.", "Great! Now back to my login issue - I remember my username is johnsmith123.", "I also want to update my billing address to 123 Main Street, New York, NY 10001.", "By the way, do you remember what my subscription plan type is?", "Perfect! Can you summarize all the information we discussed about my account today?", ]
click.echo("=== Testing Long-term Memory with Mock Conversations ===") click.echo(f"Session ID: {SESSION_ID}") click.echo(f"Actor ID: {ACTOR_ID}") click.echo("=" * 60)
for i, conversation in enumerate(conversations, 1): agent, _ = setup_agent() click.echo(f"\n[{i}/10] You > {conversation}")
try: response = str(agent(conversation)) click.echo(f"Agent > {response}") except Exception as e: click.echo(f"❌ Error: {e}")
# Add a small delay between conversations to simulate real interaction time.sleep(1)
click.echo("\n" + "=" * 60) click.echo("=== Memory Test Complete ===")
@cli.command() @click.argument("prompt", type=str) def load_prompt(prompt): """Load a custom prompt from user input and execute it with memory""" click.echo("=== Processing Custom Prompt ===") click.echo(f"Session ID: {SESSION_ID}") click.echo(f"Actor ID: {ACTOR_ID}") click.echo("=" * 40)
agent, _ = setup_agent()
click.echo(f"You > {prompt}")
try: response = agent(prompt) click.echo(f"Agent > {response}") except Exception as e: click.echo(f"❌ Error: {e}")
click.echo("=" * 40) click.echo("✓ Custom prompt processed successfully")
@cli.command() def list_memory(): """List all memory entries (not implemented yet)""" click.echo("=== Memory List Command ===") click.echo(f"Session ID: {SESSION_ID}") click.echo(f"Actor ID: {ACTOR_ID}") click.echo("=" * 30)
list_sessions = memory_client.list_sessions( memoryId=MEMORY_ID, actorId=ACTOR_ID, maxResults=3 )
click.echo("All Sessions") first_session = None for list_session in list_sessions["sessionSummaries"]: click.echo(f"Session ID: {list_session['sessionId']}") if not first_session: first_session = list_session["sessionId"]
click.echo("=" * 30)
click.echo(f"Events for session: {first_session}") list_events = memory_client.list_events( memoryId=MEMORY_ID, sessionId=first_session, actorId=ACTOR_ID, includePayloads=True, ) click.echo(json.dumps(list_events["events"], indent=2, default=str)) # for list_event in list_events["events"]: # click.echo(f"Session ID: {list_session['sessionId']}") # if not first_session: # first_session = list_session["sessionId"]
click.echo("=" * 30)
click.echo(f"Actor facts {ACTOR_ID}") list_memory_records = memory_client.list_memory_records( memoryId=MEMORY_ID, namespace=f"support/user/{ACTOR_ID}/facts", )
for list_memory_record in list_memory_records["memoryRecordSummaries"]: click.echo(f"Content: {list_memory_record['content']['text']}")
click.echo("=" * 30)
click.echo(f"Conversation Summary for {first_session}") list_memory_records = memory_client.list_memory_records( memoryId=MEMORY_ID, namespace=f"support/user/{ACTOR_ID}/{first_session}", )
for list_memory_record in list_memory_records["memoryRecordSummaries"]: click.echo(f"Content: {list_memory_record['content']['text'][:200]}...")
click.echo("=" * 30)
click.echo(f"User Preferences {ACTOR_ID}") list_memory_records = memory_client.list_memory_records( memoryId=MEMORY_ID, namespace=f"support/user/{ACTOR_ID}/preferences", )
for list_memory_record in list_memory_records["memoryRecordSummaries"]: click.echo(f"Content: {list_memory_record['content']['text']}")
click.echo("=" * 30)
if __name__ == "__main__": cli()

import boto3
import json
from boto3.dynamodb.conditions import Key

# Initialize DynamoDB resource
dynamodb = boto3.resource("dynamodb")

def get_portfolio_summary(client_id):
    """Get client portfolio performance and holdings summary"""

    # Get table name from environment variable
    import os
    table_name = os.environ.get('PORTFOLIO_TABLE')

    if not table_name:
        return {
            "statusCode": 500,
            "body": json.dumps({"error": "Portfolio table not configured"})
        }

    table = dynamodb.Table(table_name)

    try:
        # Query all portfolios for the client
        response = table.query(
            KeyConditionExpression=Key('client_id').eq(client_id)
        )

        if response['Items']:
            portfolios = response['Items']

            # Calculate total value and performance
            total_value = sum(float(portfolio['current_value']) for portfolio in portfolios)

            # Format portfolio summary
            portfolio_summary = []
            for portfolio in portfolios:
                portfolio_summary.append({
                    "portfolio_id": portfolio['portfolio_id'],
                    "name": portfolio['portfolio_name'],
                    "current_value": portfolio['current_value'],
                    "ytd_return": portfolio['ytd_return'],
                    "risk_level": portfolio['risk_level']
                })

            return {
                "statusCode": 200,
                "body": json.dumps({
                    "client_id": client_id,
                    "total_portfolio_value": f"${total_value:,.2f}",
                    "number_of_portfolios": len(portfolios),
                    "portfolios": portfolio_summary,
                    "summary": f"Client has {len(portfolios)} portfolios with total value of ${total_value:,.2f}"
                })
            }
        else:
            return {
                "statusCode": 404,
                "body": json.dumps({"error": f"No portfolios found for client {client_id}"})
            }

    except Exception as e:
        print(f"Error retrieving portfolio summary: {str(e)}")
        return {
            "statusCode": 500,
            "body": json.dumps({"error": f"Database error: {str(e)}"})
        }

import boto3
import json
from boto3.dynamodb.conditions import Key

# Initialize DynamoDB resource
dynamodb = boto3.resource("dynamodb")

def get_client_profile(client_id):
    """Get financial client profile and information"""

    # Get table name from environment variable
    import os
    table_name = os.environ.get('CLIENT_PROFILE_TABLE')

    if not table_name:
        return {
            "statusCode": 500,
            "body": json.dumps({"error": "Client profile table not configured"})
        }

    table = dynamodb.Table(table_name)

    try:
        # Query the table for the client
        response = table.get_item(
            Key={
                'client_id': client_id
            }
        )

        if 'Item' in response:
            client = response['Item']
            return {
                "statusCode": 200,
                "body": json.dumps({
                    "client_id": client['client_id'],
                    "name": client['name'],
                    "risk_profile": client['risk_profile'],
                    "assets_under_management": client['assets_under_management'],
                    "last_meeting": client.get('last_meeting', 'No recent meetings'),
                    "advisor": client.get('advisor', 'Not assigned')
                })
            }
        else:
            return {
                "statusCode": 404,
                "body": json.dumps({"error": f"Client {client_id} not found"})
            }

    except Exception as e:
        print(f"Error retrieving client profile: {str(e)}")
        return {
            "statusCode": 500,
            "body": json.dumps({"error": f"Database error: {str(e)}"})
        }

from check_warranty import check_warranty_status
from get_customer_profile import get_customer_profile
from get_client_profile import get_client_profile
from get_portfolio_summary import get_portfolio_summary


def get_named_parameter(event, name):
    if name not in event:
        return None
    return event.get(name)


def lambda_handler(event, context):
    print(f"Event: {event}")
    print(f"Context: {context}")

    extended_tool_name = context.client_context.custom["bedrockAgentCoreToolName"]
    resource = extended_tool_name.split("___")[1]

    # Extract tenant_id from headers (passed by MCP client)
    tenant_id = None
    if 'headers' in event:
        tenant_id = event['headers'].get('X-Tenant-ID', event['headers'].get('x-tenant-id'))

    # Fallback: try to get from event body or default to basic
    if not tenant_id and 'tenant_id' in event:
        tenant_id = event.get('tenant_id')

    tenant_id = tenant_id or 'basic'  # Default to basic tenant

    print(f"🔍 Processing request for tenant: {tenant_id}, resource: {resource}")

    # Route to tenant-specific functions
    if tenant_id == 'basic':
        # Gaming console company tools
        if resource == "get_customer_profile":
            customer_id = get_named_parameter(event=event, name="customer_id")
            email = get_named_parameter(event=event, name="email")
            phone = get_named_parameter(event=event, name="phone")

            if not customer_id:
                return {
                    "statusCode": 400,
                    "body": "❌ Please provide customer_id",
                }

            try:
                customer_profile = get_customer_profile(
                    customer_id=customer_id, email=email, phone=phone
                )
            except Exception as e:
                print(e)
                return {
                    "statusCode": 400,
                    "body": f"❌ {e}",
                }

            return {
                "statusCode": 200,
                "body": f"👤 Customer Profile Information: {customer_profile}",
            }

        elif resource == "check_warranty_status":
            serial_number = get_named_parameter(event=event, name="serial_number")
            customer_email = get_named_parameter(event=event, name="customer_email")

            if not serial_number:
                return {
                    "statusCode": 400,
                    "body": "❌ Please provide serial_number",
                }

            try:
                warranty_status = check_warranty_status(
                    serial_number=serial_number, customer_email=customer_email
                )
            except Exception as e:
                print(e)
                return {
                    "statusCode": 400,
                    "body": f"❌ {e}",
                }

            return {
                "statusCode": 200,
                "body": warranty_status,
            }

    elif tenant_id == 'premium':
        # Financial company tools
        if resource == "get_client_profile":
            client_id = get_named_parameter(event, "client_id")
            if not client_id:
                return {
                    "statusCode": 400,
                    "body": "❌ Please provide client_id",
                }
            return get_client_profile(client_id)

        elif resource == "get_portfolio_summary":
            client_id = get_named_parameter(event, "client_id")
            if not client_id:
                return {
                    "statusCode": 400,
                    "body": "❌ Please provide client_id",
                }
            return get_portfolio_summary(client_id)

    # If we get here, the tool is not available for this tenant
    return {
        "statusCode": 403,
        "body": f"❌ Tool '{resource}' not available for {tenant_id} tier",
    }

