from bedrock_agentcore.memory import MemoryClient
from strands.hooks.events import AgentInitializedEvent, MessageAddedEvent
from strands.hooks.registry import HookProvider, HookRegistry
import copy


class MemoryHook(HookProvider):
    def __init__(
        self,
        memory_client: MemoryClient,
        memory_id: str,
        actor_id: str,
        session_id: str,
    ):
        self.memory_client = memory_client
        self.memory_id = memory_id
        self.actor_id = actor_id
        self.session_id = session_id

    def on_agent_initialized(self, event: AgentInitializedEvent):
        """Load recent conversation history when agent starts"""
        try:
            # Load the last 5 conversation turns from memory
            recent_turns = self.memory_client.get_last_k_turns(
                memory_id=self.memory_id,
                actor_id=self.actor_id,
                session_id=self.session_id,
                k=5,
            )

            if recent_turns:
                # Format conversation history for context
                context_messages = []
                for turn in recent_turns:
                    for message in turn:
                        role = "assistant" if message["role"] == "ASSISTANT" else "user"
                        content = message["content"]["text"]
                        context_messages.append(
                            {"role": role, "content": [{"text": content}]}
                        )

                # context = "\n".join(context_messages)
                # Add context to agent's system prompt.
                event.agent.system_prompt += """
                Do not respond with user preferences or user facts. 
                Strictly use user preferences and user facts to know more about the user.
                Also be aware that this information can be outdated.
                """
                event.agent.messages = context_messages

        except Exception as e:
            print(f"Memory load error: {e}")

    def _add_context_user_query(
        self, namespace: str, query: str, init_content: str, event: MessageAddedEvent
    ):
        content = None
        memories = self.memory_client.retrieve_memories(
            memory_id=self.memory_id, namespace=namespace, query=query, top_k=3
        )

        for memory in memories:
            if not content:
                content = "\n\n" + init_content + "\n\n"

            content += memory["content"]["text"]

            if content:
                event.agent.messages[-1]["content"][0]["text"] += content + "\n\n"

    def on_message_added(self, event: MessageAddedEvent):
        """Store messages in memory"""
        messages = copy.deepcopy(event.agent.messages)
        try:
            if messages[-1]["role"] == "user" or messages[-1]["role"] == "assistant":
                if "text" not in messages[-1]["content"][0]:
                    return

                if messages[-1]["role"] == "user":
                    self._add_context_user_query(
                        namespace=f"support/user/{self.actor_id}/preferences",
                        query=messages[-1]["content"][0]["text"],
                        init_content="These are user preferences:",
                        event=event,
                    )

                    self._add_context_user_query(
                        namespace=f"support/user/{self.actor_id}/facts",
                        query=messages[-1]["content"][0]["text"],
                        init_content="These are user facts:",
                        event=event,
                    )
                self.memory_client.save_conversation(
                    memory_id=self.memory_id,
                    actor_id=self.actor_id,
                    session_id=self.session_id,
                    messages=[
                        (messages[-1]["content"][0]["text"], messages[-1]["role"])
                    ],
                )

        except Exception as e:
            raise RuntimeError(f"Memory save error: {e}")

    def register_hooks(self, registry: HookRegistry):
        registry.add_callback(MessageAddedEvent, self.on_message_added)
        registry.add_callback(AgentInitializedEvent, self.on_agent_initialized)

from agent_config.context import CustomerSupportContext from agent_config.access_token import get_gateway_access_token from agent_config.agent_task import agent_task from agent_config.streaming_queue import StreamingQueue from agent_config.jwt_utils import extract_tenant_id_from_jwt from bedrock_agentcore.runtime import BedrockAgentCoreApp from scripts.utils import get_ssm_parameter import asyncio import logging import os
# Environment flags os.environ["STRANDS_OTEL_ENABLE_CONSOLE_EXPORT"] = "true" os.environ["STRANDS_TOOL_CONSOLE_MODE"] = "enabled"
os.environ["KNOWLEDGE_BASE_ID"] = get_ssm_parameter( "/app/customersupport/knowledge_base/knowledge_base_id" )
# Logging setup logging.basicConfig(level=logging.INFO) logger = logging.getLogger(__name__)
# Bedrock app and global agent instance app = BedrockAgentCoreApp()
@app.entrypoint async def invoke(payload, context): if not CustomerSupportContext.get_response_queue_ctx(): CustomerSupportContext.set_response_queue_ctx(StreamingQueue())
if not CustomerSupportContext.get_gateway_token_ctx(): gateway_token = await get_gateway_access_token() CustomerSupportContext.set_gateway_token_ctx(gateway_token)
# Get tenant_id from payload (sent by API Gateway Lambda) tenant_id = payload.get('tenant_id', 'basic') print(f"🔍 DEBUG: Got tenant_id from payload: {tenant_id}") CustomerSupportContext.set_tenant_id_ctx(tenant_id)
user_message = payload["prompt"] actor_id = payload["actor_id"]
session_id = context.session_id
if not session_id: raise Exception("Context session_id is not set")
task = asyncio.create_task( agent_task( user_message=user_message, session_id=session_id, actor_id=actor_id, ) )
response_queue = CustomerSupportContext.get_response_queue_ctx()
async def stream_output(): async for item in response_queue.stream(): yield item await task # Ensure task completion
return stream_output()
